// Run with Dart SDK 3.13.7 (`dart run`, whose JIT has dart:mirrors), redirect stdout to
// src/dart/library/sdkMembers.ts, and format that file with `bun fmt`.
// The imports load the libraries, which dart:mirrors lists only once they are loaded.
import 'dart:async';
import 'dart:collection';
import 'dart:convert';
import 'dart:io';
import 'dart:math';
import 'dart:mirrors';

const libraries = ['dart:async', 'dart:collection', 'dart:convert', 'dart:core', 'dart:io', 'dart:math'];

String nameOf(Symbol symbol) => MirrorSystem.getName(symbol);

/** Joins names sorted, so that the generated file changes only where the SDK does. */
String names(Iterable<String> values) => (values.toSet().toList()..sort()).join(' ');

/** The instance members a class declares or inherits; `instanceMembers` leaves out abstract ones such as `Future.then`. */
Set<String> instanceNames(ClassMirror cls, [Set<ClassMirror>? visited]) {
  visited ??= {};
  if (!visited.add(cls.originalDeclaration as ClassMirror)) return {};
  final result = <String>{};
  for (final member in cls.declarations.values) {
    if (member.isPrivate) continue;
    if (member is MethodMirror && !member.isStatic && !member.isConstructor) result.add(nameOf(member.simpleName));
    if (member is VariableMirror && !member.isStatic) result.add(nameOf(member.simpleName));
  }
  final supertypes = [?cls.superclass, ...cls.superinterfaces, ?cls.mixin];
  for (final supertype in supertypes) {
    if (supertype != cls) result.addAll(instanceNames(supertype, visited));
  }
  return result;
}

void main() {
  if (!Platform.version.startsWith('3.13.7 ')) throw StateError('Run with Dart SDK 3.13.7: ${Platform.version}');
  // Every class has Object's members, which the interpreter declares.
  final objectMembers = reflectClass(Object).instanceMembers.keys.map(nameOf).toSet();
  final output = StringBuffer()
    ..writeln('// Generated by scripts/generateDartLibraryMembers.dart from Dart SDK 3.13.7. Do not edit.')
    ..writeln('// Each public class: its public instance members (with inherited ones), static members, and constructors.')
    ..writeln('export const SDK_MEMBERS: Readonly<Record<string, Readonly<Record<string, readonly [string, string, string]>>>> = {');
  for (final uri in libraries) {
    final library = currentMirrorSystem().libraries[Uri.parse(uri)]!;
    final classes = library.declarations.values.whereType<ClassMirror>().where((cls) => !cls.isPrivate).toList()
      ..sort((a, b) => nameOf(a.simpleName).compareTo(nameOf(b.simpleName)));
    output.writeln("  '$uri': {");
    for (final cls in classes) {
      final instance = names(
        instanceNames(cls)
            .map((name) => name.replaceAll('=', ''))
            .where((name) => !objectMembers.contains(name) && RegExp(r'^[A-Za-z_$][\w$]*$').hasMatch(name)),
      );
      final statics = names(
        cls.staticMembers.values
            .where((member) => !member.isPrivate)
            .map((member) => nameOf(member.simpleName).replaceAll('=', '')),
      );
      final className = nameOf(cls.simpleName);
      final constructors = names(
        cls.declarations.values
            .whereType<MethodMirror>()
            .where((member) => member.isConstructor && !member.isPrivate)
            .map((member) => nameOf(member.constructorName))
            .where((name) => name.isNotEmpty),
      );
      if (instance.isEmpty && statics.isEmpty && constructors.isEmpty) continue;
      output.writeln("    $className: ['$instance', '$statics', '$constructors'],");
    }
    output.writeln('  },');
  }
  output.writeln('};');
  stdout.write(output);
}
